import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally opponent behavior.
    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    # Endgame: exploit cooperative opponents, avoid being the sucker.
    if n >= 96:
        if opp_d * 100 <= n * 25:
            return 'D'
        if opp_d * 100 >= n * 70:
            return 'D'
        return 'C'

    # Detect pure always-defect quickly.
    if n >= 4:
        last4_d = 0
        for a, b in history[-4:]:
            if b == 'D':
                last4_d += 1
        if last4_d == 4:
            return 'D'

    # Recent window.
    window = history[-8:]
    w_opp_c = 0
    for a, b in window:
        if b == 'C':
            w_opp_c += 1
    w_len = len(window)
    w_opp_d = w_len - w_opp_c

    last_me, last_opp = history[-1]

    # Nearly all-cooperative opponent: mostly cooperate, occasional probe.
    if n > 25 and opp_d * 100 <= n * 5:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # If opponent has been defecting a lot overall, punish firmly.
    if n >= 12 and opp_d * 100 >= n * 55:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Streak handling on the opponent.
    if w_len >= 3:
        s = 0
        for a, b in window[-3:]:
            if b == 'D':
                s += 1
        if s == 3:
            return 'D'

    # Tit-for-tat with bounded forgiveness.
    if last_opp == 'D':
        # If opponent has mostly cooperated recently and we've been defecting
        # a lot ourselves, forgive to restart cooperation.
        if w_opp_c >= w_len - 1 and w_len >= 5:
            if my_d * 100 >= n * 55 and rng.random() < 0.6:
                return 'C'
        # Avoid endless mutual defection against forgiving TFT-like opponents.
        if last_me == 'D' and w_opp_d <= 1:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    if w_opp_d >= 3:
        return 'D'

    # Occasional probe against long-run cooperative opponents.
    if n > 40 and opp_d * 100 <= n * 12:
        if rng.random() < 0.1:
            return 'D'

    return 'C'
